<script setup lang="ts">
import type { URLItem } from "../types";

defineProps<{ urls: URLItem[]; filteredUrls: URLItem[]; urlsLoading: boolean; search: string; status: string; disablingId: string }>();
const emit = defineEmits<{ "update:search": [value: string]; "update:status": [value: string]; navigate: [page: "dashboard"]; copy: [value: string]; disable: [id: string]; enable: [id: string] }>();
</script>

<template>
  <section>
    <div class="mb-8 flex flex-col justify-between gap-4 sm:flex-row sm:items-end"><div><p class="mb-2 text-sm font-medium text-slate-500">Workspace</p><h1 class="text-3xl font-semibold tracking-tight sm:text-4xl">URL List.</h1><p class="mt-3 text-slate-600">Kelola semua tautan yang telah dibuat dari akunmu.</p></div><button type="button" class="rounded-md bg-slate-900 px-4 py-2.5 text-sm font-medium text-white hover:bg-slate-700" @click="emit('navigate', 'dashboard')">Buat URL baru</button></div>
    <section class="overflow-hidden rounded-xl border border-stone-300 bg-white shadow-sm"><div class="flex flex-col gap-3 border-b border-stone-200 p-4 sm:flex-row sm:items-end sm:justify-between"><div><h2 class="font-semibold">Semua URL</h2><p class="mt-1 text-xs text-slate-500">{{ filteredUrls.length }} dari {{ urls.length }} URL ditampilkan</p></div><div class="flex w-full flex-col gap-2 sm:w-auto sm:flex-row"><input :value="search" type="search" placeholder="Cari URL..." class="w-full rounded-md border border-stone-300 bg-stone-50 px-3 py-2 text-sm outline-none focus:border-slate-500 sm:w-56" @input="emit('update:search', ($event.target as HTMLInputElement).value)"><select :value="status" class="rounded-md border border-stone-300 bg-stone-50 px-3 py-2 text-sm outline-none focus:border-slate-500" @change="emit('update:status', ($event.target as HTMLSelectElement).value)"><option value="all">Semua status</option><option value="active">Aktif</option><option value="disabled">Nonaktif</option></select></div></div><div v-if="urlsLoading" class="p-8 text-center text-sm text-slate-500">Memuat tautan...</div><div v-else-if="filteredUrls.length === 0" class="p-10 text-center text-sm text-slate-500">Tidak ada URL yang cocok.</div><div v-else class="divide-y divide-stone-200"><div v-for="item in filteredUrls" :key="item.id" class="flex flex-col gap-4 p-4 sm:flex-row sm:items-center sm:justify-between"><div class="min-w-0"><div class="flex items-center gap-2"><a :href="item.short_url" target="_blank" class="truncate font-medium text-slate-900 underline underline-offset-4 hover:text-slate-600">{{ item.short_url }}</a><button type="button" class="shrink-0 text-xs text-slate-400 hover:text-slate-900" @click="emit('copy', item.short_url)">Salin</button></div><p class="mt-1 truncate text-sm text-slate-500">{{ item.original_url }}</p><p class="mt-2 text-xs text-slate-400">Dibuat {{ new Date(item.created_at).toLocaleDateString("id-ID", { day: "numeric", month: "short", year: "numeric" }) }}</p></div><div class="flex shrink-0 items-center gap-3"><span class="rounded-full px-2.5 py-1 text-[10px] font-semibold uppercase tracking-wider" :class="item.status === 'active' ? 'bg-green-50 text-green-700' : 'bg-stone-100 text-slate-400'">{{ item.status }}</span><button v-if="item.status === 'active'" type="button" :disabled="disablingId === item.id" class="text-sm text-slate-500 hover:text-red-700 disabled:opacity-50" @click="emit('disable', item.id)">{{ disablingId === item.id ? "..." : "Nonaktifkan" }}</button><button v-else type="button" :disabled="disablingId === item.id" class="text-sm text-slate-500 hover:text-green-700 disabled:opacity-50" @click="emit('enable', item.id)">{{ disablingId === item.id ? "..." : "Aktifkan kembali" }}</button></div></div></div></section>
  </section>
</template>
